88	/**
89	 * Type-safe job enqueue helper.
90	 */
91	export async function enqueueJob<K extends keyof JobPayloads>(
92	  name: K,
93	  data: JobPayloads[K],
94	  options?: { delay?: number; priority?: number }
95	): Promise<string | undefined> {
96	  const job = await getQueue().add(name, data, options)
97	  return job.id
